// Auto-activate assigned agent when issue moves to open status
// Backlog-first policy: skip if >10 issues in open queue
const SK = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InR3dGhnYXBpb3VpcWhhdnJjbnJ5Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3NDUzMTY3NiwiZXhwIjoyMDkwMTA3Njc2fQ.EyNdtvECdcHx3RuaizdfLGNRY4OJotzjE2QeOQ9Yf4Q';
const SUPA = 'https://twthgapiouiqhavrcnry.supabase.co';
const h = { apikey: SK, Authorization: 'Bearer ' + SK };
const MC_API = 'http://localhost:3000/api/issues';
const MAX_OPEN_QUEUE = 9999; // cap retired per TOD-572

const staticData = $getWorkflowStaticData('global');
if (!staticData.triggered) staticData.triggered = {};
const now = Date.now();
for (const [id, ts] of Object.entries(staticData.triggered)) {
  if (now - ts > 45 * 60 * 1000) delete staticData.triggered[id]; // re-trigger after 45min if still open
}

const allOpen = await helpers.httpRequest({
  method: 'GET',
  url: SUPA + '/rest/v1/issues?status=eq.open&select=id',
  headers: h
});
const openCount = Array.isArray(allOpen) ? allOpen.length : 0;

if (openCount > MAX_OPEN_QUEUE) {
  return [{ json: { skipped: true, reason: 'open_queue_full', openCount } }];
}

const issues = await helpers.httpRequest({
  method: 'GET',
  url: SUPA + '/rest/v1/issues?status=in.(open,product_review)&select=id,task_key,title,assignee,acceptance_criteria,started_at,status',
  headers: h
});

const AGENT_MAP = {
  'tester': 'tester', 'builder': 'builder', 'scout': 'scout', 'ops': 'ops',
  'kemuni-sme': 'kemuni-sme', 'vespera-sme': 'vespera-sme', 'main': 'main', 'KAOS': 'main',
};
const TRIGGER_URL = 'http://127.0.0.1:8787/trigger-agent';
const results = [];

for (const issue of issues) {
  if (staticData.triggered[issue.id]) continue; // will expire after 45min
  const agentId = AGENT_MAP.hasOwnProperty(issue.assignee) ? AGENT_MAP[issue.assignee] : null;
  if (!agentId) { results.push({ key: issue.task_key, action: 'skipped: ' + issue.assignee }); continue; }

  const validAgents = ['tester','builder','scout','ops','kemuni-sme','vespera-sme','main','po','designer','auditor','deployer','ux'];
  if (!validAgents.includes(agentId)) { results.push({ key: issue.task_key, action: 'skipped: ' + agentId }); continue; }

  const msg = 'Issue ' + issue.task_key + ' is ready: ' + issue.title + '. Pick it up and start work.';
  try { await helpers.httpRequest({ method: 'POST', url: TRIGGER_URL, headers: {'Content-Type':'application/json'}, body: JSON.stringify({agentId, message: msg}) }); } catch(e) {}

  staticData.triggered[issue.id] = now;

  try {
    await helpers.httpRequest({
      method: 'PATCH', url: MC_API,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: issue.id, started_at: new Date().toISOString() })
    });
  } catch(e) {}

  results.push({ key: issue.task_key, agent: agentId, action: 'activated' });
}
return [{ json: { processed: results.length, openCount, results, timestamp: new Date().toISOString() } }];

